1: import { Outlet } from "react-router";
2: import type { ReactElement } from "react";
3: import type { Route } from "./+types/route";
4: import { getAuth } from "~/lib/auth/auth.server";
5: import AppLayoutShell from "~/components/app-layout-shell";
6: 
7: /**
8:  * Clean Mode Layout
9:  *
10:  * This layout provides an ad-free experience of the application.
11:  * It mirrors the main `_app` layout but explicitly excludes ad components.
12:  * It also includes SEO protection (noindex) to prevent public indexing.
13:  */
14: 
15: export const handle = {
16:   hideAds: true,
17: };
18: 
19: export const meta: Route.MetaFunction = () => [
20:   { name: "robots", content: "noindex, nofollow" },
21: ];
22: 
23: export const loader = async ({ context, request }: Route.LoaderArgs) => {
24:   const auth = getAuth(context);
25:   const session = await auth.api.getSession({ headers: request.headers });
26: 
27:   const contactEmail = context.cloudflare.env.CONTACT_EMAIL;
28:   const baseURL = context.cloudflare.env.BETTER_AUTH_URL;
29: 
30:   return {
31:     contactEmail,
32:     baseURL,
33:     user: session?.user,
34:   };
35: };
36: 
37: const CleanLayout = ({ loaderData }: Route.ComponentProps): ReactElement => {
38:   const { contactEmail } = loaderData;
39: 
40:   return (
41:     <AppLayoutShell contactEmail={contactEmail}>
42:       <Outlet />
43:     </AppLayoutShell>
44:   );
45: };
